"use client";

import { useCallback, useEffect, useId, useRef, useState, type CSSProperties, type KeyboardEvent, type MouseEvent, type ReactNode } from 'react';
import './radial-nav.css';

export type RadialNavItem = {
  id: string;
  label: string;
  href: string;
  icon: ReactNode;
};

export type RadialNavProps = {
  items: RadialNavItem[];
  activeId?: string;
  className?: string;
  label?: string;
  onNavigate?: (id: string, event: MouseEvent<HTMLAnchorElement>) => void;
  onOpenChange?: (open: boolean) => void;
};

/** A disclosure with ordinary links arranged around its central trigger. */
export function RadialNav({ items, activeId, className = '', label = 'Explore', onNavigate, onOpenChange }: RadialNavProps) {
  const [open, setOpen] = useState(false);
  const openRef = useRef(false);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const links = useRef<Array<HTMLAnchorElement | null>>([]);
  const focusOnOpen = useRef<'first' | 'last' | null>(null);
  const panelId = useId();

  const changeOpen = useCallback((next: boolean, restoreFocus = false) => {
    if (restoreFocus) trigger.current?.focus();
    if (openRef.current === next) return;
    openRef.current = next;
    setOpen(next);
    onOpenChange?.(next);
  }, [onOpenChange]);

  useEffect(() => {
    if (!open) return;
    if (focusOnOpen.current) {
      links.current[focusOnOpen.current === 'first' ? 0 : items.length - 1]?.focus();
      focusOnOpen.current = null;
    }
    const dismiss = (event: PointerEvent) => {
      if (event.target instanceof Node && !root.current?.contains(event.target)) changeOpen(false);
    };
    document.addEventListener('pointerdown', dismiss);
    return () => document.removeEventListener('pointerdown', dismiss);
  }, [open, items.length, changeOpen]);

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === 'Escape' && openRef.current) {
      event.preventDefault();
      event.stopPropagation();
      changeOpen(false, true);
      return;
    }
    const forward = event.key === 'ArrowRight' || event.key === 'ArrowDown';
    const backward = event.key === 'ArrowLeft' || event.key === 'ArrowUp';
    if (!forward && !backward && event.key !== 'Home' && event.key !== 'End') return;
    if (!items.length) return;
    event.preventDefault();
    if (!openRef.current) {
      focusOnOpen.current = backward || event.key === 'End' ? 'last' : 'first';
      changeOpen(true);
      return;
    }
    const current = links.current.findIndex((element) => element === event.target);
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : current < 0 ? backward ? items.length - 1 : 0 : (current + (backward ? -1 : 1) + items.length) % items.length;
    links.current[next]?.focus();
  }

  return <div
    ref={root}
    className={`ac-radial-nav ${className}`.trim()}
    data-open={open}
    onKeyDown={handleKeyDown}
    onBlur={(event) => {
      if (event.relatedTarget instanceof Node && !event.currentTarget.contains(event.relatedTarget)) changeOpen(false);
    }}
  >
    <div className="ac-radial-orbit" aria-hidden="true" />
    <button
      ref={trigger}
      type="button"
      className="ac-radial-trigger"
      aria-expanded={open}
      aria-controls={panelId}
      aria-label={`${label} navigation`}
      onClick={() => changeOpen(!openRef.current)}
    >
      <span className="ac-radial-symbol" aria-hidden="true"><span /><span /><span /><span /></span>
      <span className="ac-radial-trigger-label">{label}</span>
    </button>
    <nav id={panelId} aria-label={label} hidden={!open} className="ac-radial-links">
      {open && items.map((item, index) => {
        const angle = index / items.length * Math.PI * 2 - Math.PI / 2;
        const style = {
          '--ac-radial-x': Math.cos(angle),
          '--ac-radial-y': Math.sin(angle),
          '--ac-radial-delay': `${Math.min(index * 25, 140)}ms`,
        } as CSSProperties;
        return <a
          key={item.id}
          ref={(element) => { links.current[index] = element; }}
          className="ac-radial-link"
          href={item.href}
          style={style}
          aria-current={activeId === item.id ? 'page' : undefined}
          onClick={(event) => {
            onNavigate?.(item.id, event);
            changeOpen(false, true);
          }}
        >
          <span className="ac-radial-icon" aria-hidden="true">{item.icon}</span>
          <span className="ac-radial-link-label">{item.label}</span>
        </a>;
      })}
    </nav>
  </div>;
}

.ac-radial-nav {
  --ac-radial-paper: var(--ac-surface, var(--ac-radial-nav-theme-paper, #f8f7f0));
  --ac-radial-ink: var(--ac-ink, var(--ac-radial-nav-theme-ink, #25271f));
  --ac-radial-accent: var(--ac-accent, #df5c38);
  --ac-radial-radius: min(100px, calc((100cqw - 82px) / 2));
  position: relative;
  width: 300px;
  max-width: 100%;
  height: var(--ac-radial-height, 300px);
  min-height: 260px;
  color: var(--ac-radial-ink);
  font-family: var(--ac-font, inherit);
  container-type: inline-size;
  isolation: isolate;
}
.ac-radial-nav *, .ac-radial-nav *::before, .ac-radial-nav *::after { box-sizing: border-box; }
.ac-radial-orbit { position: absolute; top: 50%; left: 50%; width: calc(var(--ac-radial-radius) * 2); height: calc(var(--ac-radial-radius) * 2); border: 1px dashed color-mix(in srgb, var(--ac-radial-ink) 17%, transparent); border-radius: 50%; transform: translate(-50%,-50%) scale(.7); opacity: 0; transition: transform 350ms ease, opacity 250ms; pointer-events: none; }
.ac-radial-nav[data-open="true"] .ac-radial-orbit { transform: translate(-50%,-50%) scale(1); opacity: 1; }
.ac-radial-trigger { position: absolute; z-index: 2; top: 50%; left: 50%; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 8px; width: 90px; height: 90px; padding: 10px 5px; border: 0; border-radius: 50%; background: var(--ac-radial-ink); color: var(--ac-radial-paper); transform: translate(-50%,-50%); box-shadow: 0 5px 0 color-mix(in srgb, var(--ac-radial-ink) 17%, transparent); cursor: pointer; font: inherit; -webkit-tap-highlight-color: transparent; }
.ac-radial-symbol { display: grid; grid-template-columns: repeat(2, 5px); gap: 4px; transition: transform 350ms cubic-bezier(.2,.8,.2,1); }
.ac-radial-symbol span { display: block; width: 5px; height: 5px; border-radius: 50%; background: currentColor; transition: border-radius 250ms; }
.ac-radial-nav[data-open="true"] .ac-radial-symbol { transform: rotate(135deg); }
.ac-radial-nav[data-open="true"] .ac-radial-symbol span { border-radius: 0; }
.ac-radial-trigger-label { max-width: 76px; font-size: 10px; font-weight: 500; line-height: 1.15; text-align: center; overflow-wrap: anywhere; }
.ac-radial-links { position: absolute; inset: 0; pointer-events: none; }
.ac-radial-links[hidden] { display: none; }
.ac-radial-link { --ac-radial-offset-x: calc(var(--ac-radial-radius) * var(--ac-radial-x)); --ac-radial-offset-y: calc(var(--ac-radial-radius) * var(--ac-radial-y)); position: absolute; top: 50%; left: 50%; display: flex; flex-direction: column; align-items: center; gap: 5px; width: 72px; min-height: 66px; padding: 0 2px 4px; border-radius: 13px; transform: translate(calc(-50% + var(--ac-radial-offset-x)),calc(-50% + var(--ac-radial-offset-y))); color: inherit; text-decoration: none; pointer-events: auto; animation: ac-radial-arrive 400ms cubic-bezier(.18,.8,.2,1) var(--ac-radial-delay) both; -webkit-tap-highlight-color: transparent; }
.ac-radial-icon { display: grid; place-items: center; width: 46px; height: 46px; border: 1px solid color-mix(in srgb, var(--ac-radial-ink) 17%, transparent); border-radius: 50%; background: var(--ac-radial-paper); box-shadow: 0 3px 0 color-mix(in srgb, var(--ac-radial-ink) 8%, transparent); transition: background 180ms, color 180ms, transform 180ms, border-color 180ms; }
.ac-radial-icon svg { width: 19px; height: 19px; }
.ac-radial-link-label { max-width: 72px; font-size: 10px; line-height: 1.2; font-weight: 500; text-align: center; overflow-wrap: anywhere; }
.ac-radial-link[aria-current="page"] .ac-radial-icon { color: var(--ac-radial-paper); background: var(--ac-radial-accent); border-color: var(--ac-radial-accent); }
.ac-radial-trigger:focus-visible, .ac-radial-link:focus-visible { outline: 2px solid var(--ac-radial-accent); outline-offset: 5px; }
@media (hover: hover) { .ac-radial-link:hover .ac-radial-icon { transform: translateY(-3px); background: var(--ac-radial-accent); border-color: var(--ac-radial-accent); color: var(--ac-radial-paper); } }
@keyframes ac-radial-arrive { from { opacity: 0; transform: translate(-50%,-50%) scale(.35); } to { opacity: 1; transform: translate(calc(-50% + var(--ac-radial-offset-x)),calc(-50% + var(--ac-radial-offset-y))) scale(1); } }
@media (prefers-reduced-motion: reduce) { .ac-radial-nav *, .ac-radial-nav *::before, .ac-radial-nav *::after { animation: none !important; transition: none !important; } }

/* Neutral defaults follow the page theme; explicit component colors keep priority. */
:where([data-theme="light"], .light) .ac-radial-nav {
  --ac-radial-nav-theme-paper: #fbfcf8;
  --ac-radial-nav-theme-ink: #25271f;
}
:where([data-theme="dark"], .dark) .ac-radial-nav {
  --ac-radial-nav-theme-paper: #242a21;
  --ac-radial-nav-theme-ink: #e8eddf;
}
